import{_ as t}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as a,o as r,c as o,al as i}from"./chunks/framework.7vp1BMOE.js";const L=JSON.parse('{"title":"Режим Повернення (VTOL)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_vtol/return.md","filePath":"uk/flight_modes_vtol/return.md"}'),l={name:"uk/flight_modes_vtol/return.md"};function n(d,e,_,h,s,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="режим-повернення-vtol" tabindex="-1">Режим Повернення (VTOL) <a class="header-anchor" href="#режим-повернення-vtol" aria-label="Permalink to &quot;Режим Повернення (VTOL)&quot;">​</a></h1><img src="'+t+'" title="Position fix required (e.g. GPS)" width="30px"><p>Режим <em>повернення</em> використовується для <em>політів засобом перевезення до безпечного місця</em> при наявності вільного шляху до безпечного пункту призначення, де він може зачекати (зависнути або обійти колом) або сісти.</p><p>VTOL vehicles use the <a href="./../flight_modes/return#rtl_type_1">Mission Landing/Rally Point</a> return type by default. У цьому типі повернення апарат піднімається на мінімальну безпечну висоту над перешкодами (за необхідності), а потім напряму летить до точки збору або початкової точки призначення місії (яка є найближчою), або додому, якщо жодна з точок збору або місійний маршрут посадки не визначені. Якщо призначенням є місійний маршрут посадки, апарат потім дотримуватиметься маршруту для посадки. If the destination is a rally point or the home location, the vehicle will fly to that destination and land.</p><p>Літальний апарат повернеться за допомогою режиму польоту (MC або FW), який він використовував у той момент, коли був активований режим повернення. Загалом, він буде дотримуватися того ж поведінкового зразка режиму повернення, що й відповідний тип транспортного засобу, але завжди перейде до режиму MC (якщо потрібно) перед посадкою.</p><p>VTOL supports the <a href="./../flight_modes/return#return_types">other PX4 return types</a>, including home/rally point return, mission path and closest safe destination. За замовчуванням рекомендується використовувати цей тип.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Режим автоматичний - для керування апаратом не потрібно втручання користувача.</li><li>Режим вимагає глобальної оцінки 3D-позиції (з GPS або виведеної з <a href="./../ros/external_position_estimation#enabling-auto-modes-with-a-local-position">локальної позиції</a>). <ul><li>Літаючі транспортні засоби не можуть переключатися на цей режим без глобального положення.</li><li>Літаючі транспортні засоби перейдуть в режим аварійної безпеки, якщо втратять оцінку положення.</li></ul></li><li>Режим вимагає встановленої домашньої позиції.</li><li>Mode prevents arming (vehicle cannot be armed while this mode is selected).</li><li>Перемикачі керування RC можуть використовуватися для зміни режимів польоту на будь-якому транспортному засобі.</li><li>Рух стіків радіокерування ігнорується.</li></ul></div><h2 id="технічнии-підсумок" tabindex="-1">Технічний підсумок <a class="header-anchor" href="#технічнии-підсумок" aria-label="Permalink to &quot;Технічний підсумок&quot;">​</a></h2><p>VTOL vehicles use the <a href="./../flight_modes/return#rtl_type_1">Mission Landing/Rally Point</a> return type by default, and return using the flying mode (MC or FW) it was using at the point when return mode was triggered.</p><h3 id="повернення-режиму-фіксованого-крила-fw" tabindex="-1">Повернення режиму фіксованого крила (FW) <a class="header-anchor" href="#повернення-режиму-фіксованого-крила-fw" aria-label="Permalink to &quot;Повернення режиму фіксованого крила (FW)&quot;">​</a></h3><p>Якщо апарат повертається як літак, він:</p><ul><li><p>Піднімається на безпечну мінімальну висоту повернення, визначену за допомогою <a href="#RTL_RETURN_ALT">RTL_RETURN_ALT</a> (безпечно вище будь-яких очікуваних перешкод). Транспортний засіб підтримує свою початкову висоту, якщо вона вище, ніж мінімальна висота повернення.</p></li><li><p>Flies via a constant-altitude path to the destination, which will be the closest of the start of a <em>mission landing pattern</em> and any rally point, or the home location if no mission landing pattern or rally points are defined. The path is chosen to be the shortest horizontal <a href="./../flight_modes/return#geofence_awareness">geofence-aware path</a>.</p></li><li><p>Якщо призначенням є місійний маршрут посадки, апарат буде дотримуватися маршруту для посадки.</p><p>Місійний маршрут посадки для літального апарату типу VTOL складається з <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_LAND_START" target="_blank" rel="noreferrer">MAV_CMD_DO_LAND_START</a>, однієї або кількох маршрутних точок розташування та <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_VTOL_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_VTOL_LAND</a>.</p></li><li><p>Якщо призначенням є точка збору або домашня локація, апарат:</p><ul><li><p>Fly to the selected <a href="#vtol-rally-point-approach-loiters">VTOL approach loiter</a> associated with that landing location (if any are defined) and use it to descend to the approach altitude. If several approach loiters are defined for that location, PX4 chooses the one that best matches the estimated wind at the landing point.</p><p>See <a href="#vtol-rally-point-approach-loiters">VTOL Rally Point Approach Loiter</a> below for information on how to define approach loiters (using <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a> items in your <em>rally plan</em>).</p></li><li><p>Loiter/spiral down to the approach altitude, or to <a href="#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a> above the destination if no approach altitude is defined.</p></li><li><p>Кружляє протягом короткого часу, визначеного <a href="#RTL_LAND_DELAY">RTL_LAND_DELAY</a>.</p></li><li><p>Fly from the approach loiter to the return destination (the rally point or home location).</p></li><li><p>Transition to MC mode at the destination and land.</p><p>Зауважте, що <a href="./../advanced_config/parameter_reference#NAV_FORCE_VT">NAV_FORCE_VT</a> ігнорується: апарат завжди сідає як мультикоптер для цих призначень.</p></li></ul></li></ul><h4 id="vtol-rally-point-approach-loiters" tabindex="-1">VTOL Rally Point Approach Loiters <a class="header-anchor" href="#vtol-rally-point-approach-loiters" aria-label="Permalink to &quot;VTOL Rally Point Approach Loiters&quot;">​</a></h4><p>VTOL <em>rally point approach loiters</em> are <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a> items associated with a particular rally point (<a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_RALLY_POINT" target="_blank" rel="noreferrer">MAV_CMD_NAV_RALLY_POINT</a>) in a <a href="./../flying/plan_safety_points">Rally plan</a>. They define options for where the VTOL can descend to the rally point approach altitude, and how it will approach the rally point. Several approach loiters can be defined for a rally point, and PX4 will choose the one that best matches the estimated wind at the landing point.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <code>MAV_CMD_NAV_LOITER_TO_ALT</code> items that define approach loiters are associated with a Rally/safety point, and are hence part of the rally point plan when used in this way — <em>not</em> the mission plan. This behaviour is not defined in the MAVLink rally point plan specification.</p></div><p>When uploading VTOL approach loiters through MAVLink, <a href="https://mavlink.io/en/services/mission.html#mission_types" target="_blank" rel="noreferrer">upload them as rally/safe-point</a> mission items (<code>MAV_MISSION_TYPE_RALLY</code>). The <code>MAV_CMD_NAV_RALLY_POINT</code> item must come first, followed by one or more <code>MAV_CMD_NAV_LOITER_TO_ALT</code> items that define the approach loiters for that rally point. The next <code>MAV_CMD_NAV_RALLY_POINT</code> starts a new landing-location block.</p><p>For each <code>MAV_CMD_NAV_LOITER_TO_ALT</code> item, <code>x/y/z</code> define the loiter center and approach altitude, and <code>param2</code> defines the loiter radius used by RTL. If <code>param2</code> is unset or zero, PX4 falls back to <a href="#RTL_LOITER_RAD">RTL_LOITER_RAD</a>.</p><p>For example, a rally upload with one rally point and two possible approach loiters would use:</p><table tabindex="0"><thead><tr><th>Sequence</th><th>Команда</th><th>Ціль</th><th>Key fields</th></tr></thead><tbody><tr><td>0</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_RALLY_POINT" target="_blank" rel="noreferrer">MAV_CMD_NAV_RALLY_POINT</a></td><td>Landing location</td><td><code>x/y/z</code>: rally latitude, longitude, altitude</td></tr><tr><td>1</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a></td><td>First VTOL approach loiter</td><td><code>x/y/z</code>: loiter latitude, longitude, altitude; <code>param2</code>: loiter radius</td></tr><tr><td>2</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a></td><td>Second VTOL approach loiter</td><td><code>x/y/z</code>: loiter latitude, longitude, altitude; <code>param2</code>: loiter radius</td></tr></tbody></table><p>Note that the approach loiter is not the back-transition point. If the selected approach loiter is far from the rally point or home location, the vehicle remains in fixed-wing mode after the loiter, flies to the destination at the approach altitude, and only then back-transitions for landing.</p><h2 id="режим-мультикоптера-mc-повернення" tabindex="-1">Режим мультикоптера (MC) Повернення <a class="header-anchor" href="#режим-мультикоптера-mc-повернення" aria-label="Permalink to &quot;Режим мультикоптера (MC) Повернення&quot;">​</a></h2><p>Якщо повертається у вигляді мультикоптера:</p><ul><li>Поведінка залишається такою самою, за винятком того, що транспортний засіб летить як багтороторний і дотримується налаштувань багтороторних засобів.</li><li>Зокрема, якщо здійснюється посадка на точку збору або додому, транспортний засіб використовує <a href="#RTL_CONE_ANG">RTL_CONE_ANG</a> замість простої <a href="#RTL_RETURN_ALT">RTL_RETURN_ALT</a> для визначення мінімальної безпечної висоти повернення. Для отримання додаткової інформації див. пояснення &quot;конуса&quot; у <a href="./../flight_modes/return#minimum-return-altitude">Режимі повернення (загальний транспортний засіб) &gt; Мінімальна висота повернення</a>.</li></ul><h2 id="параметри" tabindex="-1">Параметри <a class="header-anchor" href="#параметри" aria-label="Permalink to &quot;Параметри&quot;">​</a></h2><p>Параметри RTL перелічені в <a href="./../advanced_config/parameter_reference#return-mode">Референсі параметрів &gt; Режим повернення</a>. Якщо використовується місійна посадка, значення <a href="#RTL_RETURN_ALT">RTL_RETURN_ALT</a> та <a href="#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a> є важливими. Інші параметри стають актуальними, якщо призначенням є точка збору або домашня локація.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="RTL_TYPE"></a><a href="./../advanced_config/parameter_reference#RTL_TYPE">RTL_TYPE</a></td><td>Тип повернення.</td></tr><tr><td><a id="RTL_APPR_FORCE"></a><a href="./../advanced_config/parameter_reference#RTL_APPR_FORCE">RTL_APPR_FORCE</a></td><td>[VTOL FW only] If set, PX4 only considers home or rally-point RTL destinations when a valid VTOL approach loiter is defined for that landing location. Mission landing patterns are unaffected.</td></tr><tr><td><a id="RTL_RETURN_ALT"></a><a href="./../advanced_config/parameter_reference#RTL_RETURN_ALT">RTL_RETURN_ALT</a></td><td>Висота повернення в метрах (за замовчуванням: 60 м). Якщо вже знаходиться вище цієї висоти, транспортний засіб повернеться на поточну висоту.</td></tr><tr><td><a id="RTL_CONE_ANG"></a><a href="./../advanced_config/parameter_reference#RTL_CONE_ANG">RTL_CONE_ANG</a></td><td>Половина кута конуса, який визначає висоту повернення транспортного засобу RTL. Значення (у градусах): 0, 25, 45, 65, 80, 90. Зауважте, що 0 означає &quot;без конуса&quot; (завжди повертається на висоту <code>RTL_RETURN_ALT</code> або вище), тоді як 90 показує, що транспортний засіб повинен повертатися на поточну висоту або <code>RTL_DESCEND_ALT</code> (яка вище).</td></tr><tr><td><a id="RTL_DESCEND_ALT"></a><a href="./../advanced_config/parameter_reference#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a></td><td>Мінімальна висота повернення і висота, на якій повітряне судно сповільнює або зупиняє своє початкове зниження з вищої висоти повернення (за замовчуванням: 30 м)</td></tr><tr><td><a id="RTL_LAND_DELAY"></a><a href="./../advanced_config/parameter_reference#RTL_LAND_DELAY">RTL_LAND_DELAY</a></td><td>Час очікування на висоті <code>RTL_DESCEND_ALT</code> перед посадкою (за замовчуванням: 0.5 с) - за замовчуванням цей період короткий, щоб транспортний засіб просто сповільнився, а потім враз відразу приземлився. Якщо встановлено значення -1, система буде кружляти на висоті <code>RTL_DESCEND_ALT</code> замість посадки. Затримка надається для того, щоб ви могли налаштувати час для розгортання шасі для посадки (автоматично спрацьовує).</td></tr><tr><td><a id="RTL_LOITER_RAD"></a><a href="./../advanced_config/parameter_reference#RTL_LOITER_RAD">RTL_LOITER_RAD</a></td><td>[Літаки з фіксованим крилом] Радіус кола очікування (на висоті <a href="#RTL_LAND_DELAY">RTL_LAND_DELAY</a>.</td></tr><tr><td><a id="MIS_TKO_LAND_REQ"></a><a href="./../advanced_config/parameter_reference#MIS_TKO_LAND_REQ">MIS_TKO_LAND_REQ</a></td><td>Вказує, чи <em>необхідний</em> місійний маршрут посадки або зльоту. Зазвичай літаки з фіксованим крилом встановлюють це для вимоги до посадкового маршруту, але VTOL - ні.</td></tr></tbody></table><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../flight_modes/return">Режим повернення (Загальний)</a></li><li><a href="./../flight_modes_mc/return">Режим повернення (Мультикоптер)</a></li><li><a href="./../flight_modes_fw/return">Режим повернення (з нерухомим крилом)</a></li></ul>',28)])])}const f=a(l,[["render",n]]);export{L as __pageData,f as default};
